    "org_id" "uuid",
    "project_id" "uuid",
    "title" "text" NOT NULL,
    "description" "text",
    "severity" "text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text",
    "cvss_score" numeric(3,1),
    "cvss_vector" "text",
    "cve_id" "text",
    "cve_verified" boolean DEFAULT false,
    "cwe_id" "text",
    "owasp_category" "text",
    "affected_component" "text",
    "endpoint_url" "text",
    "proof_of_concept" "text",
    "impact" "text",
    "remediation" "text",
    "reference_links" "text"[],
    "tags" "text"[],
    "found_by" "uuid",
    "assigned_to" "uuid",
    "verified_by" "uuid",
    "is_ai_generated" boolean DEFAULT false,
    "ai_model_used" "text",
    "raw_scanner_data" "jsonb",
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "version" integer DEFAULT 1,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "ticket_id" "text",
    "remediation_proof_url" "text",
    "remediation_notes" "text",
    "resolved_at" timestamp with time zone,
    "resolved_by" "uuid",
    "assigned_by" "uuid",
    CONSTRAINT "vulnerabilities_cvss_score_check" CHECK ((("cvss_score" >= (0)::numeric) AND ("cvss_score" <= (10)::numeric))),
    CONSTRAINT "vulnerabilities_severity_check" CHECK (("severity" = ANY (ARRAY['critical'::"text", 'high'::"text", 'medium'::"text", 'low'::"text", 'informational'::"text"]))),
    CONSTRAINT "vulnerabilities_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'resolved'::"text", 'verified'::"text", 'reopened'::"text", 'closed'::"text", 'accepted_risk'::"text", 'false_positive'::"text"])))
);


--
