-- Name: audit_log audit_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "audit_insert" ON "public"."audit_log" FOR INSERT WITH CHECK (("public"."is_super_admin"() OR (("public"."my_role"() = 'admin'::"text") AND ("org_id" = "public"."my_org_id"()))));


--
-- Name: audit_log audit_insert_super_admin; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "audit_insert_super_admin" ON "public"."audit_log" FOR INSERT WITH CHECK ("public"."is_super_admin"());


