--
-- Name: cicd_configs cicd_configs_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "cicd_configs_select" ON "public"."cicd_configs" FOR SELECT USING ((("org_id" = "public"."my_org_id"()) AND (NOT "public"."is_super_admin"())));


--
-- Name: cicd_configs cicd_configs_update; Type: POLICY; Schema: public; Owner: -
--

