--
-- Name: vuln_comments comments_delete; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "comments_delete" ON "public"."vuln_comments" FOR DELETE USING ((("author_id" = "auth"."uid"()) AND ("now"() <= ("created_at" + '00:02:00'::interval))));


--
-- Name: vuln_comments comments_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "comments_insert" ON "public"."vuln_comments" FOR INSERT WITH CHECK ((("author_id" = "auth"."uid"()) AND (EXISTS ( SELECT 1
   FROM "public"."vulnerabilities" "v"
  WHERE ("v"."id" = "vuln_comments"."vuln_id")))));


--
-- Name: vuln_comments comments_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "comments_select" ON "public"."vuln_comments" FOR SELECT USING ((EXISTS ( SELECT 1
   FROM "public"."vulnerabilities" "v"
  WHERE ("v"."id" = "vuln_comments"."vuln_id"))));


--
