-- Name: project_members members_delete; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "members_delete" ON "public"."project_members" FOR DELETE USING ((("project_id" IN ( SELECT "projects"."id"
   FROM "public"."projects"
  WHERE ("projects"."org_id" = "public"."my_org_id"()))) AND
CASE
    WHEN ("public"."my_role"() = 'admin'::"text") THEN true
    WHEN ("public"."my_role"() = 'program_manager'::"text") THEN (((EXISTS ( SELECT 1
       FROM "public"."projects"
      WHERE (("projects"."id" = "project_members"."project_id") AND ("projects"."created_by" = "auth"."uid"())))) OR "public"."check_project_membership"("project_id", "auth"."uid"())) AND (( SELECT "profiles"."role"
       FROM "public"."profiles"
      WHERE ("profiles"."id" = "project_members"."profile_id")) = ANY (ARRAY['security_engineer'::"text", 'guest'::"text"])))
    ELSE false
END));


